s_branch label_ShiftVectorComponents0_GLVW0

label_ShiftVectorComponents0_GLVW0:  /// end shift0

/* shift vector components d1 */
v_mov_b32 v17, s[sgprWorkGroup1]
v_mul_i32_i24 v17, -0x100, v17                     // wg*MT
v_add_co_u32 v17, vcc, s[sgprSizesFree+1], v17     // wgMT = Size - wg*MT
v_mov_b32 v18, 0x100                               // MT
v_cmp_lt_u32 s[8:9], v17, v18                      // wgMT < MT
v_cndmask_b32 v17, v18, v17, s[8:9]                // wgMT = (wgMT < MT) ? wgMT : MT
v_lshrrev_b32 v19, 7, v[vgprSerial]                // 19 = Serial / 128
v_and_b32 v19, 1, v19                              // v19 = v19 % 2
v_lshrrev_b32 v20, 4, v17                          // 20 = 17 / 16
v_and_b32 v20, 1, v20                              // v20 = v20 % 2
v_cmp_eq_u32 s[8:9], v20, v19                      // wave_id == block_belong_to_wave?
v_cndmask_b32 v17, v18, v17, s[8:9]                // wgMT = (wgMT < MT) ? wgMT : MT

/* mbReg: which mb block need to shift, mb(matrixInstCoal(16) * VectorWidth(1)) */
v_lshrrev_b32 v18, 4, v17                          // 18 = 17 / 16
v_lshlrev_b32 v20, 0, v19                          // v20 = v19 * 1
v_sub_u32 v18, v18, v20

/* gbReg: glvw block id */
v_lshrrev_b32 v20, 3, v17                          // 20 = 17 / 8

/* tgbReg: glvw block id */
v_lshrrev_b32 v21, 4, v[vgprSerial]                // 21 = Serial / 16
v_and_b32 v21, 3, v21                              // v21 = v21 % 4
v_lshlrev_b32 v21, 2, v21                          // v21 = v21 * 4
v_lshrrev_b32 v21, 3, v21                          // 21 = 21 / 8
v_lshlrev_b32 v19, 1, v19                          // v19 = v19 * 2
v_add_co_u32 v21, vcc, v19, v21                    // tgbReg = (tid_coal * continOut) / GLVW
v_sub_u32 v20, v20, v21

/* vwReg: glvw in which vw block? */
v_and_b32 v19, 3, v17                              // permute register between threads
v_lshrrev_b32 v19, 3, v19                          // permute register between threads

/* rReg : reminder of M_size % GlobalReadVectorWidth */
v_and_b32 v21, 7, v17                              // v21 = v17 % 8
v_cmp_eq_u32 vcc, v21, 0x1                         // wgMT%VW == 1
s_cbranch_vccnz label_ShiftVectorComponents1_GLVW1 // branch to shift d1 r=1
v_cmp_eq_u32 vcc, v21, 0x2                         // wgMT%VW == 2
s_cbranch_vccnz label_ShiftVectorComponents1_GLVW2 // branch to shift d1 r=2
v_cmp_eq_u32 vcc, v21, 0x3                         // wgMT%VW == 3
s_cbranch_vccnz label_ShiftVectorComponents1_GLVW3 // branch to shift d1 r=3
v_cmp_eq_u32 vcc, v21, 0x4                         // wgMT%VW == 4
s_cbranch_vccnz label_ShiftVectorComponents1_GLVW4 // branch to shift d1 r=4
v_cmp_eq_u32 vcc, v21, 0x5                         // wgMT%VW == 5
s_cbranch_vccnz label_ShiftVectorComponents1_GLVW5 // branch to shift d1 r=5
v_cmp_eq_u32 vcc, v21, 0x6                         // wgMT%VW == 6
s_cbranch_vccnz label_ShiftVectorComponents1_GLVW6 // branch to shift d1 r=6
v_cmp_eq_u32 vcc, v21, 0x7                         // wgMT%VW == 7
s_cbranch_vccnz label_ShiftVectorComponents1_GLVW7 // branch to shift d1 r=7

/* no shifting */
s_branch label_ShiftVectorComponents1_GLVW0

